changeSet.sql:
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM area_zone WHERE hamlet_id IS NULL) THEN RAISE EXCEPTION 'Unmapped legacy areas: migration stopped'; END IF;
 IF EXISTS (SELECT 1 FROM area_zone GROUP BY hamlet_id HAVING count(*)>1) THEN RAISE EXCEPTION 'Duplicate legacy areas: resolve business fields before migration'; END IF;
 IF EXISTS (SELECT 1 FROM household h JOIN area_zone a ON a.id=h.area_zone_id WHERE h.hamlet_id IS DISTINCT FROM a.hamlet_id) THEN RAISE EXCEPTION 'Conflicting household hamlet IDs: migration stopped'; END IF;
END $$;
ALTER TABLE hamlet ADD COLUMN officer_in_charge varchar(255), ADD COLUMN officer_phone varchar(255), ADD COLUMN population_count integer, ADD COLUMN household_count integer, ADD COLUMN boundary_geo_json text;
UPDATE hamlet h SET officer_in_charge=a.officer_in_charge, officer_phone=a.officer_phone, population_count=a.population_count, household_count=a.household_count, boundary_geo_json=a.boundary_geo_json FROM area_zone a WHERE a.hamlet_id=h.id;
CREATE TABLE rbac_assignment_native (subject varchar(255) NOT NULL REFERENCES rbac_profile(subject) ON DELETE CASCADE, hamlet_id bigint NOT NULL REFERENCES hamlet(id), PRIMARY KEY(subject,hamlet_id));
INSERT INTO rbac_assignment_native SELECT DISTINCT r.subject,a.hamlet_id FROM rbac_assignment r JOIN area_zone a ON a.id=r.area_zone_id;
DO $$ BEGIN
 IF (SELECT count(*) FROM rbac_assignment_native) <> (SELECT count(*) FROM rbac_assignment) THEN RAISE EXCEPTION 'Assignment count mismatch'; END IF;
END $$;
UPDATE rbac_profile SET version=version+1 WHERE subject IN (SELECT subject FROM rbac_assignment);
UPDATE rbac_profile SET data=(data::jsonb - 'areaZoneIds' - 'hamletIds')::text;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM rbac_setting s WHERE s.kind='units' AND NOT EXISTS (SELECT 1 FROM area_zone a WHERE a.id::text=s.id)) THEN RAISE EXCEPTION 'Unmapped unit setting: migration stopped'; END IF;
END $$;
UPDATE rbac_setting s SET id=a.hamlet_id::text, data=jsonb_set(s.data::jsonb,'{id}',to_jsonb(a.hamlet_id::text))::text FROM area_zone a WHERE s.kind='units' AND s.id=a.id::text;
DROP TABLE rbac_assignment;
ALTER TABLE rbac_assignment_native RENAME TO rbac_assignment;
ALTER TABLE gis_building ADD COLUMN hamlet_id bigint REFERENCES hamlet(id);
UPDATE gis_building b SET hamlet_id=a.hamlet_id FROM area_zone a WHERE b.area_zone_id=a.id;
ALTER TABLE gis_building DROP COLUMN area_zone_id;
CREATE INDEX ix_gis_building_hamlet ON gis_building(hamlet_id);
ALTER TABLE household DROP COLUMN area_zone_id;
CREATE INDEX IF NOT EXISTS ix_household_hamlet_direct ON household(hamlet_id);
DROP TABLE area_zone;
